    """
    Effectue l'addition, la soustraction, la multiplication et la division de deux nombres.

    Args:
        a (float): Le premier nombre.
        b (float): Le deuxième nombre.

    Returns:
        dict: Un dictionnaire contenant les résultats des quatre opérations.
    """
    try:
        addition = a + b
        soustraction = a - b
        multiplication = a * b

        # Gestion de la division par zéro
