### 2. C

En C, les fonctions doivent retourner une valeur spécifique. Pour gérer la division par zéro sans utiliser de `try/catch`, nous utiliserons un pointeur vers une variable (`int*`) pour retourner un code de statut (0 pour succès, 1 pour erreur).

```c
#include <stdio.h>

// Fonction qui retourne le résultat via un pointeur et un code de statut
int calcul(double nombre1, double nombre2, char operation, double* resultat) {
    if (operation == '+') {
        *resultat = nombre1 + nombre2;
        return 0; // Succès
    } else if (operation == '-') {
        *resultat = nombre1 - nombre2;
        return 0; // Succès
    } else if (operation == '*') {
        *resultat = nombre1 * nombre2;
        return 0; // Succès
    } else if (operation == '/') {
        if (nombre2 == 0.0) {
            return 1; // Erreur : Division par zéro
        }
        *resultat = nombre1 / nombre2;
        return 0; // Succès
    } else {
        return 2; // Erreur : Opération non valide
    }
}

int main() {
    double resultat;
    int status;

    // Test de division par zéro
    status = calcul(10.0, 0.0, '/', &resultat);
    if (status == 0) {
        printf("Résultat: %f\n", resultat);
    } else {
        printf("Erreur lors du calcul.\n");
    }

    // Test d'addition
    status = calcul(5.5, 2.5, '+', &resultat);
    if (status == 0) {
        printf("Addition: %f\n", resultat);
    }

    return 0;
}
```

